"""RPC Book Two, Title Eight (Arts. 246-266-D): crimes against persons."""

RA9346 = {'t': 'RA 9346 (2006)', 's': 'Prohibits the imposition of the death penalty; reclusion perpetua is imposed instead, without eligibility for parole (and the crime is still called “qualified”).', 'u': '#/code/ra9346'}
RA9262 = {'t': 'Anti-Violence Against Women and Their Children Act (RA 9262)', 's': 'Physical, sexual, psychological and economic violence against a wife, former wife, or a woman with whom the offender has or had a sexual or dating relationship, or her child, is punished separately; battered woman syndrome is a defense (Sec. 26).', 'u': ''}
RA7610 = {'t': 'Special Protection of Children Act (RA 7610), Sec. 5(b), as amended by RA 11648', 's': 'Sexual intercourse or lascivious conduct with a child exploited in prostitution or subjected to other sexual abuse; when the victim is under sixteen, prosecution is for rape or lascivious conduct under the Code with the heavier penalty.', 'u': ''}


def add(n):
    n(246, 'Parricide: killing one’s father, mother or child (legitimate or illegitimate), any other legitimate ascendant or descendant, or one’s spouse.',
      k=['A person is killed.', 'The accused killed him or her.', 'The deceased is the accused’s father, mother or child (legitimate or illegitimate), other legitimate ascendant or descendant, or legitimate spouse.'],
      t=['Only parents and children may be illegitimate; other ascendants and descendants must be legitimate. Killing an illegitimate grandchild is murder or homicide, not parricide.', 'The spouse must be a legitimate spouse — a void marriage means no parricide.', 'The relationship must be alleged in the information; otherwise it cannot qualify the killing.', 'A stranger who conspires with the relative is liable for murder or homicide, not parricide (relationship is personal).'],
      i=[RA9346], chk=['his father, mother, or child', 'his spouse'])
    n(247, 'Death or physical injuries under exceptional circumstances: a legally married person who surprises his spouse in the act of sexual intercourse with another and kills or seriously injures either or both in the act or immediately after suffers only destierro; less serious or slight injuries are exempt. The same applies to parents as to their daughters under eighteen living with them, and their seducers.',
      k=['A legally married person (or a parent) surprises the spouse (or minor daughter) in the act of sexual intercourse.', 'He or she kills or inflicts serious physical injuries in the act or immediately thereafter.', 'He or she did not promote or facilitate the prostitution of the spouse or daughter, or consent to the infidelity.'],
      t=['Art. 247 does not define a crime; it grants a privilege and a near-exemption. Destierro is meant to protect the accused from retaliation, not to punish.', '“Immediately thereafter” means the killing is the continuation of the act of discovery, without a break that allows reflection.', 'Third persons injured by stray shots: the accused may still be liable for the injuries to them through imprudence.'],
      d=[{'n': 'People v. Abarca', 'c': 'G.R. No. 74433, September 14, 1987', 'h': 'A husband who surprised his wife with her paramour, got a gun and shot the paramour within an hour was entitled to Art. 247; the article does not define a felony, and the injuries to bystanders were treated as less serious physical injuries through simple imprudence.', 'r': 'Nature of Art. 247.'}],
      chk=['surprised his spouse in the act of committing sexual intercourse', 'destierro'])
    n(248, 'Murder: killing another (not parricide or infanticide) with any qualifying circumstance — treachery, abuse of superior strength, aid of armed men, means to weaken the defense or insure impunity; price, reward or promise; by inundation, fire, poison, explosion, shipwreck, derailment, attack on a vessel, motor vehicle or similar great waste and ruin; on the occasion of a calamity; evident premeditation; or cruelty, by deliberately augmenting the suffering of the victim or outraging or scoffing at his person or corpse.',
      k=['A person was killed.', 'The accused killed him.', 'With at least one qualifying circumstance of Art. 248.', 'Not parricide or infanticide.'],
      t=['Treachery: (1) means of execution that gave the person attacked no opportunity to defend himself; (2) deliberately or consciously adopted. A sudden attack is not treachery if it was not deliberately chosen.', 'Only one qualifying circumstance is needed; others present become generic aggravating circumstances.', 'Qualifying circumstances must be alleged in the information (Rules of Criminal Procedure, Rule 110, Secs. 8-9).', 'Death in the text is now reclusion perpetua without parole (RA 9346).'],
      i=[RA9346], chk=['treachery', 'evident premeditation', 'price, reward or promise'])
    n(249, 'Homicide: killing another without any of the circumstances of murder, and not parricide or infanticide.', t=['Intent to kill is presumed from the fact of death; for frustrated or attempted homicide it must be proven (e.g., from the weapon used, the wounds, the words uttered).'], chk=['without the attendance of any of the circumstances'])
    n(250, 'For frustrated parricide, murder or homicide, the court may impose a penalty one degree lower than that for the frustrated felony, and for attempted, two degrees lower than that for the attempt.', t=['This is discretionary (“may”).'], chk=['may impose'])
    n(251, 'Death in a tumultuous affray: several persons, not organized into groups, quarrel and assault one another in a confused and tumultuous manner; someone is killed; and it cannot be ascertained who killed him. Those who inflicted serious physical injuries are punished; if they cannot be identified, all who used violence on the victim.',
      k=['Several persons, not composing groups organized to attack each other.', 'They quarrel and assault each other in a confused and tumultuous manner.', 'Someone is killed in the course of the affray.', 'The killer cannot be identified.', 'It can be determined who inflicted serious physical injuries or who used violence.'],
      t=['If the killer is identified, he is liable for homicide or murder; Art. 251 applies only when he cannot be identified.', 'If the participants were organized groups, the crime is homicide or murder (conspiracy).'],
      chk=['confused and tumultuous manner'])
    n(252, 'Physical injuries in a tumultuous affray: only serious (or less serious) physical injuries are inflicted on participants and the person responsible cannot be identified; all who used violence on the injured party are punished.', chk=['tumultuous'])
    n(253, 'Giving assistance to suicide: assisting another to commit suicide; heavier if the assistance extends to doing the killing oneself. If the suicide is not consummated, a lower penalty applies.',
      t=['A person who attempts suicide is not punished.', 'Euthanasia (mercy killing by a third person) is homicide or murder in Philippine law, not assistance to suicide, unless the person merely helped the patient kill himself.'],
      chk=['assist another to commit suicide'])
    n(254, 'Discharge of firearms (as amended by RA 11926): (a) shooting at another with a firearm, without intent to kill, unless the facts constitute frustrated or attempted parricide, murder, homicide or a heavier crime; (b) wilful and indiscriminate discharge of any firearm or device usable as one; (c) one degree higher for military or law-enforcement personnel not on duty. The offender’s firearm license is cancelled and he is perpetually disqualified from holding one.',
      t=['For (a), the firearm must be aimed at the victim; firing into the air near someone is not “shooting at another” (it may be (b)).', 'If intent to kill is shown, the crime is attempted or frustrated homicide or murder.'],
      chk=['wilfully and indiscriminately discharge', 'summarily cancelled'])
    n(255, 'Infanticide: killing a child less than three days old. The penalty is that for parricide or murder; if committed by the mother to conceal her dishonor, or by maternal grandparents for the same purpose, a lower penalty applies.',
      t=['If the child is three days old or more, the crime is parricide (if by a parent) or murder.', 'The child must have been born alive and capable of independent life; killing a fetus is abortion.', 'Concealing dishonor benefits only the mother and the maternal grandparents.'],
      chk=['less than three days of age', 'concealing her dishonor'])
    n(256, 'Intentional abortion: (1) by violence on the pregnant woman; (2) without violence and without her consent; (3) with her consent.', k=['A pregnant woman.', 'Violence or drugs or other means are used to cause the abortion.', 'The fetus dies, in the womb or after expulsion.', 'The abortion is intended.'], t=['If the fetus is expelled alive and capable of independent life and then killed, the crime is infanticide or murder.'], chk=['intentionally cause an abortion'])
    n(257, 'Unintentional abortion: abortion caused by violence on a pregnant woman, without intent to cause it.', t=['The offender must know of the pregnancy, or it must be visible, and must have used violence; if the woman is also killed, it is a complex crime (Art. 48).'], chk=['by violence, but unintentionally'])
    n(258, 'Abortion practiced by the woman herself, or by her parents with her consent; lower penalties if she acted to conceal her dishonor.', chk=['practice an abortion upon herself'])
    n(259, 'Abortion practiced by a physician or midwife, and dispensing of abortives by a pharmacist without a proper prescription.', chk=['physician or midwife'])
    n(260, 'Killing or injuring an adversary in a duel; seconds are punished as accomplices.', chk=['adversary in a duel'])
    n(261, 'Challenging another to a duel, inciting another to give or accept a challenge, or publicly scoffing at a person for refusing a challenge.', chk=['challenge to a duel'])
    n(262, 'Mutilation: (1) intentionally depriving another, totally or partially, of an essential organ for reproduction (castration); (2) any other intentional mutilation, by lopping or clipping off any part of the body.',
      t=['Mutilation requires intent to deprive the victim of the body part; an injury that results in loss of a body part without that intent is serious physical injuries.'],
      d=[{'n': 'Aguirre v. Secretary of Justice', 'c': 'G.R. No. 170723, March 3, 2008', 'h': 'A vasectomy performed on a mentally impaired man at his guardian’s instance was not mutilation: there was no malicious intent to deprive him of an organ for reproduction, and the procedure did not remove the organ.', 'r': 'Intent in mutilation.'}],
      chk=['essential organ for reproduction'])
    n(263, 'Serious physical injuries, graded by the result: insanity, imbecility, impotence or blindness; loss of speech, hearing, smell, an eye, a hand, foot, arm or leg, or the use of any of them, or incapacity for the work habitually engaged in; deformity, loss of another part of the body, or incapacity for labor for more than ninety days; illness or incapacity for labor for more than thirty days. Heavier if against relatives listed in Art. 246 or with the circumstances of murder.',
      t=['There is no intent to kill; if there is, the crime is attempted or frustrated homicide or murder.', 'Deformity requires a visible and permanent physical ugliness (e.g., loss of front teeth may qualify).'],
      chk=['more than ninety days', 'more than thirty days'])
    n(264, 'Administering injurious substances or beverages: knowingly administering an injurious substance, or taking advantage of the victim’s weakness of mind or credulity, causing serious physical injuries, without intent to kill.', chk=['without intent to kill'])
    n(265, 'Less serious physical injuries: injuries that incapacitate the victim for labor for ten days or more (but not more than thirty), or require medical assistance for the same period; heavier if there was manifest intent to insult or offend, or circumstances adding ignominy, or against persons in authority or relatives.', chk=['ten (10) days or more'])
    n(266, 'Slight physical injuries and maltreatment: injuries incapacitating the victim for one to nine days, or requiring medical assistance for that period; injuries not preventing work and not requiring medical assistance; and ill-treatment by deed without causing injury.', t=['Ill-treatment without injury (a slap) may instead be slander by deed (Art. 359) if done to dishonor.'], chk=['nine (9) days'])
    n('266-a', 'Rape (as amended by RA 11648, 2022) is committed in two ways. (1) Rape by sexual intercourse: a person who has carnal knowledge of another person through force, threat or intimidation; when the victim is deprived of reason or unconscious; by fraudulent machination or grave abuse of authority; or when the victim is under sixteen or demented, even without those circumstances. (2) Rape by sexual assault: a person who, under any of those circumstances, inserts his penis into another person’s mouth or anal orifice, or any instrument or object into another’s genital or anal orifice.',
      k=['Rape by sexual intercourse is now gender-neutral: “a person … another person” (RA 11648 replaced “a man … a woman”).', 'Statutory rape: the victim is under sixteen (under twelve before RA 11648) or demented; consent and force are immaterial.', 'Close-in-age exception: no liability if the victim is under sixteen but the age difference is not more than three years and the act is consensual, non-abusive and non-exploitative — never if the victim is under thirteen.', 'Rape by sexual assault: any person may commit it against any person.'],
      t=['Apply the law in force when the act was committed: acts before RA 11648 took effect are judged by the earlier text (“a man … a woman”, “under twelve”).', 'There is no frustrated rape: any penetration, however slight, consummates rape by sexual intercourse (People v. Orita, 1990).', 'Rape is a crime against persons since RA 8353 (1997): it is prosecuted like any public crime, and the victim’s pardon does not extinguish it (except marriage, Art. 266-C).', 'When the victim is a child, check RA 7610, Sec. 5(b) and People v. Tulagan (2019) on which law and nomenclature apply.'],
      d=[{'n': 'People v. Orita', 'c': 'G.R. No. 88724, April 3, 1990', 'h': 'There is no frustrated rape: once there is penetration, however slight, the crime is consummated; without it, the crime is at most attempted rape or acts of lasciviousness.', 'r': 'Stages of rape.'},
         {'n': 'People v. Tulagan', 'c': 'G.R. No. 227363, March 12, 2019', 'h': 'The Court laid down guidelines on when sexual intercourse or lascivious conduct with a child is prosecuted under the Code (as rape or acts of lasciviousness) or under RA 7610, Sec. 5(b), and the proper designation of the offense and penalty in each case.', 'r': 'RA 7610 and the Code.'},
         {'n': 'G.R. No. 280727 (Supreme Court, 2026; per Leonen, J.)', 'c': 'reported July 2026', 'h': 'The Court held that RA 11648 made rape by sexual intercourse gender-neutral: since 2022 a woman may be liable for rape of a man, and men are recognized as victims. The case itself was decided under the law in force when the act was committed.', 'r': 'Gender neutrality after RA 11648. Verified from news reports; read the decision before citing it.'}],
      i=[RA7610], chk=['By a person who shall have carnal knowledge of another person', 'under sixteen (16) years of age', 'not more than three (3) years', 'under thirteen (13) years of age'])
    n('266-b', 'Penalties for rape. Rape by sexual intercourse: reclusion perpetua; reclusion perpetua to death with a deadly weapon or by two or more persons, or when the victim becomes insane, or attempted rape with homicide. Death (now reclusion perpetua without parole) for rape with homicide and for qualified rape — e.g., victim under eighteen and offender a parent, ascendant, step-parent, guardian, relative within the third civil degree, or common-law spouse of the parent; victim under seven; offender knew of the victim’s mental disability; and the other circumstances listed. Rape by sexual assault: prision mayor, higher when qualified.',
      t=['Qualifying circumstances (minority plus relationship, for example) must be alleged and proved; otherwise the rape is simple.', 'Rape with homicide is a special complex crime: all killings on the occasion of the rape are merged into it.', 'Under RA 9346 the penalty is reclusion perpetua, but the offense is still designated as qualified rape and is not eligible for parole.'],
      i=[RA9346], chk=['deadly weapon or by two or more persons', 'third civil degree', 'below seven (7) years old'])
    n('266-c', 'Effect of pardon: the subsequent valid marriage between the offender and the offended party extinguishes the criminal action or the penalty. Where the legal husband is the offender, the wife’s subsequent forgiveness extinguishes the action or penalty, unless the marriage is void ab initio.',
      t=['Marital rape is a crime (the husband can be the offender), and the wife’s forgiveness extinguishes it.', 'In multiple-offender rape, marriage to one offender extinguishes only that offender’s liability.'],
      chk=['subsequent valid marriage', 'void ab initio'])
    n('266-d', 'Presumptions: any physical overt act manifesting resistance, in any degree, or circumstances that render the victim incapable of giving valid consent, may be accepted as evidence of rape by sexual intercourse.', t=['Resistance is not an element of rape; it is only evidence of lack of consent. A victim frozen by fear need not resist.'], chk=['manifesting resistance'])
